import csv
from collections import Counter

def load(f):
    with open(f) as fh:
        return list(csv.reader(fh))

print("=" * 30, "ae_ip.csv")
try:
    R = load("ae_ip.csv")
    print("rows:", len(R))
    print("header:", R[0])
    for r in R[1:3]:
        print(r)
    hdr = [h.lower() for h in R[0]]
    def find(*names):
        for i, h in enumerate(hdr):
            for n in names:
                if n in h:
                    return i
        return None
    iy, im = find("year"), find("month")
    if iy is not None and im is not None:
        print("--- 2017-2020 monthly rows ---")
        for r in R[1:]:
            if len(r) > max(iy, im) and r[iy] in ("2017", "2018", "2019", "2020"):
                print(r)
    elif iy is not None:
        print("--- all rows (no month col) ---")
        for r in R[1:]:
            print(r)
except Exception as e:
    print("ERR", e)

print("=" * 30, "ip_claims.csv")
try:
    C = load("ip_claims.csv")
    print("rows:", len(C))
    print("header:", C[0])
    hdr = [h.lower() for h in C[0]]
    iy = None
    for i, h in enumerate(hdr):
        if "year" in h:
            iy = i
            break
    if iy is None:
        for i, h in enumerate(hdr):
            if "date" in h:
                iy = i
                break
    print("year/date col idx:", iy)
    if iy is not None:
        c = Counter()
        for r in C[1:]:
            if len(r) > iy:
                c[r[iy][:4]] += 1
        print("claims by year:", dict(sorted(c.items())))
except Exception as e:
    print("ERR", e)

